let s,tool='feed',building=null,selected=1,paused=false,speed=1,sound=false,audio=null,zoom=1,pan={x:0,y:0},size={w:1000,h:650},effects=[],last=0,uiClock=0,saveClock=0,toastTimer,drag=null,hover=null;
function creature(x,y,id){return{id,x,y,tx:x,ty:y,food:75,clean:78,happy:70,health:100,age:0,repro:0,wait:0,act:'正在观察你',seed:rand(0,6)}}
function terrain(x,y){if(x<0||y<0||x>=N||y>=N)return'void';if((x-10.5)**2/130+(y-10.5)**2/122>1)return'void';if((x>=15&&y>=4&&y<=8)||(x>=17&&y<=12&&y>=3))return'water';return'grass'}
function initial(){const objects=[];for(let x=1;x<N-1;x++)for(let y=1;y<N-1;y++){if(terrain(x,y)!=='grass'||Math.hypot(x-10,y-11)<3)continue;let n=(x*173+y*97)%31;if(n<5)objects.push({x,y,type:n<3?'tree':'rock',amount:8,regen:0});}return{version:1,time:0,wood:24,gems:12,food:30,creatures:[creature(10.2,11,1)],objects,buildings:[],nextId:2,stage:0,answered:false,storm:0,eventAt:155,autoAt:0,echo:false,log:[]}}
