$('reset-help').onclick=()=>{$('help-dialog').close();$('reset-dialog').showModal()};$('restart').onclick=()=>$('reset-dialog').showModal();$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{s=initial();selected=1;effects=[];paused=false;speed=1;pan={x:0,y:0};zoom=1;$('pause').textContent='Ⅱ';$('speed').textContent='1×';setTool('feed');save();$('reset-dialog').close();toast('一个新的世界诞生了')};
$('respond').onclick=()=>{s.answered=true;s.creatures.forEach(c=>c.happy=clamp(c.happy+8,0,100));toast('它们记住了你的回应');beep(660);updateUI()};
function resize(){const r=canvas.getBoundingClientRect();size={w:r.width,h:r.height};canvas.width=Math.floor(r.width);canvas.height=Math.floor(r.height);ctx.imageSmoothingEnabled=false}new ResizeObserver(resize).observe(canvas);
function scale(){return Math.min(size.w/900,size.h/630)*zoom*(size.w<550?1.42:1.08)}
function project(x,y,z=0){const k=scale();return{x:size.w*.49+(x-y)*TW*k+pan.x,y:size.h*.49+((x+y)-21)*TH*k-z*k+pan.y}}
